def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 5:
        return 'C'

    # Count recent opponent defections
    recent_window = min(10, n)
    recent_defections = sum(1 for i in range(n - recent_window, n) if history[i][1] == 'D')
    total_defections = sum(1 for h in history if h[1] == 'D')

    # If opponent has defected recently, consider retaliation
    if recent_defections >= 3:
        # Tit-for-tat style: if they defected last round, defect
        if history[-1][1] == 'D':
            return 'D'
        # But occasionally forgive
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    # Check for patterns suggesting opponent will defect
    if n >= 2:
        # If opponent defected after our cooperation, punish
        if history[-1][0] == 'C' and history[-1][1] == 'D':
            return 'D'
        # If opponent cooperated after our defection, forgive and cooperate
        if history[-1][0] == 'D' and history[-1][1] == 'C':
            return 'C'

    # If opponent is very cooperative, cooperate
    if total_defections == 0:
        # Occasionally test to prevent being exploited, but rarely
        if n > 50 and rng.random() < 0.02:
            return 'D'
        return 'C'

    # Defection rate
    defection_rate = total_defections / n

    # If opponent defects more than 30% of the time, defect more often
    if defection_rate > 0.3:
        if rng.random() < 0.7:
            return 'D'
        return 'C'

    # If opponent defects between 10-30%, retaliate proportionally
    if defection_rate > 0.1:
        if rng.random() < 0.3:
            return 'D'
        return 'C'

    # Mostly cooperative opponent - cooperate with occasional probing
    if n > 30 and rng.random() < 0.03:
        return 'D'

    return 'C'
